/**
 * The deterministic demo track catalog for the NeatRacing voxel racer.
 *
 * WHY THIS EXISTS (the user-directed LD-08 amendment — spec §13.5 / AC-100):
 * the demo historically booted ONE pinned track (`neatracing-demo-loop`,
 * generated from the shipped boot fixture). Phase 4 replaces the
 * single-track boot surface with a NAMED deterministic catalog of >= 4
 * variants — the pinned demo loop PLUS its reverse + mirrored free-variants
 * PLUS one additional seeded layout — ALL generated by the existing
 * deterministic track generator
 * (`examples/racing_curriculum/track/track.generator.ts`).
 *
 * DETERMINISM LAW (RED-P4-7): every variant spec is a deterministic
 * function of the catalog entry it is resolved from. `generateTrack` is a
 * pure function of its `{seed, layoutVersion, sizeBucket}` determinism key,
 * and the two derivative variants (reverse / mirrorX — the LD-08
 * "free additions") are pure deterministic transforms of that generated
 * spec. Resolving the same variant id twice yields identical geometry
 * every time; no wall clock, no RNG outside the generator key, no viewport
 * adaptation (the shipped boot fixture carries none).
 *
 * THE FROZEN CONTRACT
 * (`examples/neatRacing/track/track.catalog.test.ts` — a BYTE-FROZEN
 * read-only witness, RED-P4-FROZEN; the 6 RED-P4-7 its are the green
 * targets flipped BY NAME) probes this module as follows:
 * - it reads the named constant exports `NEATRACING_DEMO_TRACK_CATALOG`
 *   (this map) and `NEATRACING_DEMO_TRACK_VARIANT_COUNT` (this count);
 * - it reads every member id from the entry `id` field and requires the
 *   pinned demo loop id `neatracing-demo-loop` to stay a member;
 * - it discovers the variant resolver BY CAPABILITY, probing exported
 *   `/resolve/i`-named functions FIRST — this module exports EXACTLY ONE
 *   resolve-named function (`resolveTrackVariantSpec`), so the discovery
 *   can never shadow it; the transform helpers below are deliberately
 *   module-private and catalog entries deliberately carry NO spec-like
 *   fields (no `segments` / `splineSamples` / `spec` on entries), so the
 *   discovery fallback can never mistake an entry for a resolver.
 *
 * CONSUMERS: the AC-101 host selection control
 * (`examples/neatRacing/host/track.selector.ts`, landing with the
 * P4-S3-select-restart slice) resolves the selected variant through
 * `resolveTrackVariantSpec`, and the boot tuple keeps carrying the selected
 * `trackId` (the AC-026 same-tuple law). The single pinned
 * `NEATRACING_DEMO_TRACK_ID` boot constant retires into this catalog at
 * that slice (no dual path, no deferred cleanup).
 */

import { generateTrack } from '../../racing_curriculum/track/track.generator';
import type {
  SplineSample,
  TrackAabb,
  TrackGeneratorInput,
  TrackPitBox,
  TrackSegment,
  TrackSpec,
} from '../../racing_curriculum/track/track.generator.types';

/**
 * How a catalog entry derives its geometry from the deterministic generator.
 *
 * - `identity`: the generated spec is published untouched (the pinned demo
 *   loop and the additional seeded layout).
 * - `reverse`: the generated loop traversed in the opposite direction — a
 *   pure deterministic transform (LD-08 stays free; no second generator).
 * - `mirrorX`: the generated loop mirrored across the vertical axis
 *   (`x -> -x`) — a pure deterministic transform.
 */
export type NeatRacingDemoTrackTransform = 'identity' | 'reverse' | 'mirrorX';

/**
 * One named variant of the demo track catalog.
 *
 * Entries carry ONLY the derivation recipe (generation inputs + transform
 * kind) — never a precomputed spec — so the catalog stays a lie-proof data
 * table: every geometry must be produced by the deterministic generator at
 * resolve time, and the frozen contract's capability discovery can never
 * mistake an entry for a resolved spec.
 */
export type NeatRacingDemoTrackCatalogEntry = {
  /** Stable variant id (the selection key and the tuple `trackId`). */
  readonly id: string;
  /** Human-facing label for the variant in the selection UI. */
  readonly displayName: string;
  /**
   * The generator determinism key for this variant
   * (no `viewport` — the shipped boot fixture carries none, and the
   * viewport-less generator profile is the demo's canonical geometry).
   */
  readonly generation: Pick<
    TrackGeneratorInput,
    'seed' | 'layoutVersion' | 'sizeBucket'
  >;
  /** How the generated spec becomes the variant's published geometry. */
  readonly transform: NeatRacingDemoTrackTransform;
};

/**
 * The catalog member the demo boots by default (the pinned demo loop). This
 * is the retirement home of the single pinned `NEATRACING_DEMO_TRACK_ID`
 * boot constant (AC-101 retires the browser-entry literal into the catalog
 * in the same step — no dual path).
 */
export const NEATRACING_DEMO_TRACK_CATALOG_DEFAULT_ID = 'neatracing-demo-loop';

/**
 * The shipped boot generation fixture for the pinned demo loop.
 *
 * Mirrors the demo-track fixture previously inlined at the browser-entry
 * boot site (`NEATRACING_DEMO_TRACK_GENERATION = { seed: 42, layoutVersion:
 * 1, sizeBucket: 'large' }`) so the pinned member resolves EXACTLY the
 * shipped geometry (no boot-default regression, RED-P4-7 its 6).
 */
const NEATRACING_DEMO_TRACK_BOOT_GENERATION: Pick<
  TrackGeneratorInput,
  'seed' | 'layoutVersion' | 'sizeBucket'
> = {
  seed: 42,
  layoutVersion: 1,
  sizeBucket: 'large',
};

// Boot constants are frozen in place (the same hardening the generator
// applies to every resolved spec via freezeTrackSpec): a runtime bug must
// not be able to re-point the pinned boot generation or a pinned member id.
Object.freeze(NEATRACING_DEMO_TRACK_BOOT_GENERATION);

/**
 * The named deterministic demo track catalog (AC-100).
 *
 * Keyed by variant id; the pinned demo loop is the FIRST member by
 * declaration order so `Object.values` iteration always starts from the
 * boot default. The reverse and mirrored members share the pinned loop's
 * generation key on purpose — their geometry is the pinned loop's generated
 * spec transformed deterministically (the LD-08 free variants), which keeps
 * "its reverse / its mirror" literally true instead of a same-seed charade.
 * The last member is the additional seeded layout (a distinct determinant
 * key — the data-row seed is a named-choice value, like the shipped `42`).
 */
export const NEATRACING_DEMO_TRACK_CATALOG: Readonly<
  Record<string, NeatRacingDemoTrackCatalogEntry>
> = {
  [NEATRACING_DEMO_TRACK_CATALOG_DEFAULT_ID]: {
    id: NEATRACING_DEMO_TRACK_CATALOG_DEFAULT_ID,
    displayName: 'Demo Loop',
    generation: NEATRACING_DEMO_TRACK_BOOT_GENERATION,
    transform: 'identity',
  },
  'neatracing-demo-loop-reverse': {
    id: 'neatracing-demo-loop-reverse',
    displayName: 'Demo Loop Reverse',
    generation: NEATRACING_DEMO_TRACK_BOOT_GENERATION,
    transform: 'reverse',
  },
  'neatracing-demo-loop-mirrored': {
    id: 'neatracing-demo-loop-mirrored',
    displayName: 'Demo Loop Mirrored',
    generation: NEATRACING_DEMO_TRACK_BOOT_GENERATION,
    transform: 'mirrorX',
  },
  // The additional seeded layout (spec §13.5): a distinct determinism key so
  // its geometry differs from every pinned-loop derivative. The seed value
  // is data (the shipped fixture pins `42` inline the same way).
  'neatracing-demo-alt-circuit': {
    id: 'neatracing-demo-alt-circuit',
    displayName: 'Alt Circuit',
    generation: { seed: 1337, layoutVersion: 1, sizeBucket: 'large' },
    transform: 'identity',
  },
};

// Freeze the catalog map and every member entry: variant ids are pin-level
// named constants (LD-07 no-magic-strings discipline) and pinned choices
// must be immutable at runtime, not just frozen-by-convention.
Object.values(NEATRACING_DEMO_TRACK_CATALOG).forEach((entry) => {
  Object.freeze(entry);
  // Depth-1 hardening: entries that share the pinned BOOT_GENERATION key
  // re-freeze the same frozen object (a no-op there), while inline member
  // generation literals get frozen symmetrically (review F-1 closure).
  Object.freeze(entry.generation);
});
Object.freeze(NEATRACING_DEMO_TRACK_CATALOG);

/**
 * The declared variant count of the demo track catalog (AC-100).
 *
 * Derived from the catalog itself instead of hand-maintained so the count
 * and the catalog size can never disagree (a stale hand-written count is a
 * lie — RED-P4-7 its 3 fails the moment they drift).
 */
export const NEATRACING_DEMO_TRACK_VARIANT_COUNT: number = Object.keys(
  NEATRACING_DEMO_TRACK_CATALOG,
).length;

/**
 * Resolve one catalog variant to its deterministic `TrackSpec`.
 *
 * This is the SOLE `/resolve/i`-named export of the module (the frozen
 * contract's capability discovery probes resolve-named exports first, so a
 * second resolve-named function could shadow this one). The call is pure:
 * the same variant id resolves to identical geometry on every call
 * (RED-P4-7 its 4) because the generator and the transforms below are pure
 * functions.
 *
 * @param trackId - The catalog variant id to resolve. Only ids present in
 *   `NEATRACING_DEMO_TRACK_CATALOG` resolve; any other id throws a named
 *   membership error so a typo can never silently boot a wrong track.
 * @returns The deterministic spec for the selected variant.
 * @throws When `trackId` is not a catalog member.
 */
export function resolveTrackVariantSpec(trackId: string): TrackSpec {
  const entry = NEATRACING_DEMO_TRACK_CATALOG[trackId];
  if (!entry) {
    throw new Error(
      `NEATRACING_DEMO_TRACK_CATALOG has no variant id "${trackId}" — known ids: ` +
        Object.keys(NEATRACING_DEMO_TRACK_CATALOG).join(', ') +
        '.',
    );
  }
  const generated = generateTrack(entry.generation);
  if (entry.transform === 'reverse') {
    return reverseNeatRacingTrackSpec(generated);
  }
  if (entry.transform === 'mirrorX') {
    return mirrorXNeatRacingTrackSpec(generated);
  }
  return generated;
}

/**
 * Derive the REVERSE variant of a generated loop spec (LD-08 free variant).
 *
 * The segments are re-chained so the closed-loop invariant survives the
 * traversal flip: every chord swaps its endpoints and the chord order
 * reverses, so the last chord again ends where the first chord starts. The
 * spline samples are re-emitted in the opposite traversal order — the old
 * LAST chord becomes the new FIRST chord with its samples walked backwards
 * — and every sample is re-indexed (`segmentIndex`, the within-segment
 * sample position and the running `globalIndex`) so the ownership metadata
 * stays truthful against the re-chained segments. The physical points
 * (`x`, `y` and the driveable `width`) are all unchanged: the same loop is
 * simply driven the other way.
 *
 * Direction-relative metadata flips sign with the traversal handedness (a
 * counter-clockwise loop becomes clockwise, so the inward normal flips):
 * the optional per-sample `innerOffsetWorld` is negated when present.
 *
 * Sign convention (why negation, not magnitude mirroring): the published
 * `innerOffsetWorld` is a SIGNED left-normal offset, not a distance — the
 * generator emits a positive magnitude and each consumer applies its own
 * team sign (cf. the lane-point math in
 * examples/racing_curriculum/renderer/racing.renderer.ts). Negating the
 * stored sample value keeps that contract intact: under this transform each
 * team keeps its physical lane on the same road. Pit boxes are UNCHANGED —
 * an entrance corridor is a physical region relative to the loop shape, and
 * reversing the drive direction does not move it.
 */
function reverseNeatRacingTrackSpec(spec: TrackSpec): TrackSpec {
  const reversedSegments: TrackSegment[] = spec.segments
    .map((segment) => ({
      startX: segment.endX,
      startY: segment.endY,
      endX: segment.startX,
      endY: segment.startY,
      width: segment.width,
    }))
    .reverse();

  const samplesBySegmentIndex = new Map<number, SplineSample[]>();
  for (const sample of spec.splineSamples) {
    const bucket = samplesBySegmentIndex.get(sample.segmentIndex) ?? [];
    bucket.push(sample);
    samplesBySegmentIndex.set(sample.segmentIndex, bucket);
  }

  const reversedSamples: SplineSample[] = [];
  let globalIndex = 0;
  for (
    let newSegmentIndex = 0;
    newSegmentIndex < reversedSegments.length;
    newSegmentIndex += 1
  ) {
    const oldSegmentIndex = reversedSegments.length - 1 - newSegmentIndex;
    const bucket = samplesBySegmentIndex.get(oldSegmentIndex) ?? [];
    for (
      let bucketIndex = bucket.length - 1;
      bucketIndex >= 0;
      bucketIndex -= 1
    ) {
      const sample = bucket[bucketIndex];
      reversedSamples.push({
        x: sample.x,
        y: sample.y,
        width: sample.width,
        segmentIndex: newSegmentIndex,
        sampleIndexWithinSegment: bucket.length - 1 - bucketIndex,
        globalIndex,
        laneCount: sample.laneCount,
        laneWidthWorld: sample.laneWidthWorld,
        innerOffsetWorld:
          sample.innerOffsetWorld === undefined
            ? undefined
            : -sample.innerOffsetWorld,
      });
      globalIndex += 1;
    }
  }

  return {
    seed: spec.seed,
    layoutVersion: spec.layoutVersion,
    sizeBucket: spec.sizeBucket,
    segments: reversedSegments,
    splineSamples: reversedSamples,
    pitBoxes: spec.pitBoxes,
    laneCount: spec.laneCount,
    laneWidthWorld: spec.laneWidthWorld,
  };
}

/**
 * Derive the MIRRORED variant of a generated loop spec (LD-08 free
 * variant): every x coordinate negates (`x -> -x`), the driveable widths
 * and the traversal order are preserved, and the sample ownership metadata
 * is carried over untouched (mirroring does not reverse the traversal).
 *
 * The chord chain still closes under negation (negating connected endpoints
 * keeps them connected) and the handedness flips, so the direction-relative
 * `innerOffsetWorld` negates when present — same rule as the reverse
 * transform.
 *
 * Sign convention (same contract as reverse): the published
 * `innerOffsetWorld` is a SIGNED left-normal offset, not a distance — the
 * generator emits a positive magnitude and each consumer applies its own
 * team sign (cf. the lane-point math in
 * examples/racing_curriculum/renderer/racing.renderer.ts). Negating the
 * stored sample value keeps that contract intact while x mirrors: under
 * this transform the team-0 lane point is the EXACT mirror image of the
 * identity variant's team-0 lane point. Pit boxes are mirrored across the
 * same axis: an axis-aligned box at `[x, x + width]` becomes
 * `[-(x + width), -x]`, keeping the box footprint on the mirrored geometry.
 */
function mirrorXNeatRacingTrackSpec(spec: TrackSpec): TrackSpec {
  const mirroredSegments: TrackSegment[] = spec.segments.map((segment) => ({
    startX: -segment.startX,
    startY: segment.startY,
    endX: -segment.endX,
    endY: segment.endY,
    width: segment.width,
  }));

  const mirroredSamples: SplineSample[] = spec.splineSamples.map((sample) => ({
    x: -sample.x,
    y: sample.y,
    width: sample.width,
    segmentIndex: sample.segmentIndex,
    sampleIndexWithinSegment: sample.sampleIndexWithinSegment,
    globalIndex: sample.globalIndex,
    laneCount: sample.laneCount,
    laneWidthWorld: sample.laneWidthWorld,
    innerOffsetWorld:
      sample.innerOffsetWorld === undefined
        ? undefined
        : -sample.innerOffsetWorld,
  }));

  return {
    seed: spec.seed,
    layoutVersion: spec.layoutVersion,
    sizeBucket: spec.sizeBucket,
    segments: mirroredSegments,
    splineSamples: mirroredSamples,
    pitBoxes: spec.pitBoxes?.map((pitBox) => mirrorXNeatRacingPitBox(pitBox)),
    laneCount: spec.laneCount,
    laneWidthWorld: spec.laneWidthWorld,
  };
}

/**
 * Mirror one axis-aligned box across the vertical axis (`x -> -x`) while
 * keeping the box footprint (`x' = -(x + width)`, width unchanged).
 */
function mirrorXNeatRacingAabb(box: TrackAabb): TrackAabb {
  return {
    x: -(box.x + box.width),
    y: box.y,
    width: box.width,
    height: box.height,
  };
}

/**
 * Mirror one pit descriptor across the vertical axis: the entrance corridor
 * AABB, the optional rendered stall box and the optional box center all
 * move with their track half; the owning team index is preserved.
 */
function mirrorXNeatRacingPitBox(pitBox: TrackPitBox): TrackPitBox {
  return {
    teamIndex: pitBox.teamIndex,
    entranceCorridor: mirrorXNeatRacingAabb(pitBox.entranceCorridor),
    boxCenter:
      pitBox.boxCenter === undefined
        ? undefined
        : { x: -pitBox.boxCenter.x, y: pitBox.boxCenter.y },
    pitBox:
      pitBox.pitBox === undefined
        ? undefined
        : mirrorXNeatRacingAabb(pitBox.pitBox),
  };
}
